// Gap audit: dimensions with harm weights (plain JS)
const DIMENSIONS = [
  { name: "evaluation", weight: 3 },
  { name: "guardrails", weight: 3 },
  { name: "observability", weight: 2 },
  { name: "cost", weight: 1 },
  { name: "fallbacks", weight: 2 },
  { name: "review-ops", weight: 2 },
  { name: "incidents", weight: 1 },
];
function auditGap(scores) {
  // scores: {dimension: 0|1|2} — 0 absent, 1 partial, 2 owned
  return DIMENSIONS.map((d) => ({
    ...d,
    score: scores[d.name] ?? 0,
    risk: d.weight * (2 - (scores[d.name] ?? 0)),
  })).sort((a, b) => b.risk - a.risk); // fix highest risk first
}
// Priority = harm weight × gap size: money/safety dimensions outrank cost polish.

