  { name: 'guardrails', weight: 3 },
  { name: 'observability', weight: 2 },
  { name: 'cost', weight: 1 },
  { name: 'fallbacks', weight: 2 },
  { name: 'review-ops', weight: 2 },
  { name: 'incidents', weight: 1 },
];
function auditGap(scores) {
  return DIMENSIONS.map((d) => ({ ...d, score: scores[d.name] ?? 0, risk: d.weight * (2 - (scores[d.name] ?? 0)) })).sort((a, b) => b.risk - a.risk);
}
const ranked = auditGap({ evaluation: 1, guardrails: 0, observability: 1, cost: 2, fallbacks: 0, 'review-ops': 1, incidents: 0 });
console.log(ranked.slice(0, 3).map((r) => r.name + ':' + r.risk).join(','));
console.log('top fix: ' + ranked[0].name);

